let nextIsn = 0;

// pick this connection's initial sequence number
function generateIsn(srcIp, srcPort, dstIp, dstPort) {
  nextIsn += 64000;          // bump a global counter per connection
  return nextIsn >>> 0;
}

// build the ACK field for a received SYN that carried `peerSeq`
function ackForSyn(peerSeq) {
  return peerSeq;            // acknowledge the SYN
}

// build the ACK field after receiving `len` data bytes starting at `seq`
function ackForData(seq, len) {
  return (seq + len) >>> 0;
}
